export function getMethodTranslation(methodId: string, locale: Locale): MethodLocaleEntry {
    return METHOD_I18N[locale]?.[methodId] ?? VIDEO_V3_METHODS[locale]?.[methodId] ?? TEXT_V3_METHODS[locale]?.[methodId] ?? NEW_METHODS_FALLBACK[locale]?.[methodId] ?? SCIENTIFIC_V14_METHODS[locale]?.[methodId] ?? VGEN_METHODS[locale]?.[methodId] ?? METHOD_I18N.en[methodId] ?? VIDEO_V3_METHODS.en?.[methodId] ?? TEXT_V3_METHODS.en?.[methodId] ?? NEW_METHODS_FALLBACK.en?.[methodId] ?? SCIENTIFIC_V14_METHODS.en?.[methodId] ?? VGEN_METHODS.en?.[methodId] ?? { name: methodId, description: "" };
}
